window.AUTH=window.AUTH||{};window.AUTH["24-1068"]={"d":"24-1068","id":"2025/24-1068","n":"Monsanto Company v. Durnell","briefs":[{"k":"petitioner","label":"Brief of petitioner Monsanto Company","date":"2026-02-23","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/397048/20260223143047764_24-1068%20Final%20Monsanto%20Co.%20v%20Durnell%20merits%20opening%20brief.pdf","side":"pet","n":81},{"k":"united-states","label":"Brief amicus curiae of the United States","date":"2026-03-02","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/399785/20260302183259184_24-1068%20Monsanto%20tsac.pdf","side":"us","n":74},{"k":"respondent","label":"Brief of respondent John L. Durnell","date":"2026-03-25","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/401848/20260325162306480_24-1068%20Brief.pdf","side":"res","n":68},{"k":"united-states","label":"Brief amicus curiae of United States Senator Cory Booker","date":"2026-04-01","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/403423/20260401135526093_Amicus%20Brief%20of%20Senator%20Booker%20Final.pdf","side":"us","n":18},{"k":"reply","label":"Reply of petitioner Monsanto Company","date":"2026-04-17","url":"https://www.supremecourt.gov/DocketPDF/24/24-1068/404756/20260417143840724_1.%202026-04-17%20Monsanto%20v.%20Durnell%20Reply%20Final.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/609us1r61_3314.pdf","tr":true,"items":[{"t":"case","label":"Ardestani v. INS","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"sum":"Administrative deportation proceedings are not adversary adjudications \"under section 554\" and thus do not fall within the category of proceedings for which the EAJA has waived sovereign immunity and authorized the award of attorney's fees and costs.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Bates v. Dow Agrosciences LLC","cite":"544 U.S. 431","y":2005,"id":"2004/03-388","sc":1,"op":39,"ar":16,"sum":"The Court held that the peanut farmers could sue Dow in state court.","sumSrc":"Oyez","by":{"0":"2, 4, 5, 6, 26, 29, 32, 33, 34, 35, 40","1":"3-5, 7, 12, 15-21, 23, 25, 27, 28, 33","2":"2, 3, 4, 10, 10–11, 12, 16, 18, 31, 33, 34, 44, 45, 46, 48, 49, 50","3":"2, 11, 18","4":"2, 6, 7, 15"}},{"t":"case","label":"CTIA v. City of Berkeley","cite":"928 F.3d 832","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/928/832/","by":{"0":"52"}},{"t":"case","label":"Freightliner Corp. v. Myrick","cite":"514 U.S. 280","y":1995,"id":"1994/94-286","sc":1,"sum":"In separate state common-law suits, respondents alleged that the absence of an antilock braking system (ABS) in tractor-trailers manufactured by petitioners constituted a negligent design defect that caused accidents injuring one respondent and killing another's spouse. The District Court granted summary judgments for petitioners, holding that respondents' claims were pre-empted by the National Traffic and Motor …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Mason v. SmithKline Beecham Corp.","cite":"596 F.3d 387","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/596/387/","by":{"0":"42"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"op":1,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"0":"30, 32, 34","1":"15, 20","4":"5"}},{"t":"case","label":"Merck Sharp & Dohme Corp. v. Albrecht","cite":"587 U.S. 299","y":2019,"id":"2018/17-290","sc":1,"sum":"“Clear evidence” that the FDA would not have approved a change to a drug’s label—thus pre-empting a state-law failure-to-warn claim—is evidence showing that the drug manufacturer fully informed the FDA of the justifications for the warning required by state law and that the FDA, in turn, informed the drug manufacturer that the FDA would not approve a change to the drug’s label to include that warning; the question of agency disapproval is primarily one of law for a judge to decide.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"47, 48","1":"20, 29, 30, 32, 34","2":"3, 36, 42, 43","4":"23"}},{"t":"case","label":"Moore v. Ford Motor Co.","cite":"332 S.W.3d 749","y":2011,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.3d/332/749/","op":2,"by":{"0":"40, 41","1":"16, 24","2":"3, 12, 13"}},{"t":"case","label":"Mut. Pharm. Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"op":2,"sum":"The Court found that federal law preempts state law design-defect claims.","sumSrc":"Oyez","by":{"0":"43, 45, 46","1":"29, 30, 34","2":"19, 37, 44","4":"22"}},{"t":"case","label":"Nat’l Ass’n of Wheat Growers v. Bonta","cite":"85 F.4th 1263","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/85/1263/","by":{"0":"12, 13, 15, 16, 17, 18, 52","4":"8"}},{"t":"case","label":"NRDC v. EPA","cite":"38 F.4th 34","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/38/34/","op":1,"by":{"0":"17, 31, 49","1":"10, 28","2":"15"}},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"564 U.S. 604","y":2011,"id":"2010/09-993","sc":1,"op":2,"ar":5,"sum":"The Court held that generic drug makers cannot be sued for not warning about potentially dangerous side effects on their drug labels, even when they follow federal rules that only require their labels to match those of their brand-name equivalents.","sumSrc":"Oyez","by":{"0":"21, 44, 45, 46, 47, 48","1":"3, 13, 29, 30-33","2":"36","4":"17, 22"}},{"t":"case","label":"Reckitt Benckiser, Inc. v. Jackson","cite":"762 F. Supp. 2d 34","y":2011,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/762/34/","by":{"0":"39","1":"26"}},{"t":"case","label":"Riegel v. Medtronic, Inc.","cite":"552 U.S. 312","y":2008,"id":"2007/06-179","sc":1,"op":22,"ar":8,"sum":"The Court, in an 8-1 decision, affirmed the Second Circuit and granted summary judgment in favor of Medtronic. The Court's opinion, written by Justice Antonin Scalia, noted that the MDA pre-empted state common law claims for defective devices such as this one.","sumSrc":"Oyez","by":{"0":"28, 29, 37, 39, 43","1":"12, 21, 22, 34","2":"49, 50","4":"4, 5, 13, 14"}},{"t":"case","label":"Rodriguez v. Suzuki Motor Co.","cite":"996 S.W.2d 47","y":1999,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/996/47/","op":1,"by":{"0":"41","2":"13"}},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"op":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) authorizes the Environmental Protection Agency (EPA) to use data submitted by an applicant for registration of a covered product (hereinafter pesticide) in evaluating the application of a subsequent applicant, and to disclose publicly some of the submitted data. Under the dataconsideration provisions of § 3, as amended in 1978, applicants now are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 7","1":"4, 26"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Schaffner v. Monsanto Corp.","cite":"113 F.4th 364","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/113/364/","op":2,"by":{"0":"10, 30, 31, 37","1":"22, 26, 31, 33","4":"20"}},{"t":"case","label":"Stearns Elec. Paste Co. v. EPA","cite":"461 F.2d 293","y":1972,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/461/293/","by":{"0":"4, 5"}},{"t":"case","label":"Stengel v. Medtronic Inc.","cite":"704 F.3d 1224","y":2013,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/704/1224/","by":{"0":"39"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"op":2,"ar":3,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"0":"44, 47","1":"29, 30, 34","2":"39"}},{"t":"usc","label":"7 U.S.C. § 136","url":"https://www.law.cornell.edu/uscode/text/7/136","subs":["(q)(1)","(q)(1)(E)","(q)(2)","(t)","(x)","(bb)","(q)(1)(A)","(q)(1)(B)","(q)(1)(G)","(q)","(u)"],"stext":{"head":"§136. Definitions","paras":[[0,"For purposes of this subchapter—"],[0,"(a) Active ingredient"],[0,"The term \"active ingredient\" means—"],[1,"(1) in the case of a pesticide other than a plant regulator, defoliant, desiccant, or nitrogen stabilizer, an ingredient which will prevent, destroy, repel, or mitigate any pest;"],[1,"(2) in the case of a plant regulator, an ingredient which, through physiological action, will accelerate or retard the rate of growth or rate of maturation or otherwise alter the behavior of ornamental or crop plants or the product thereof;"],[1,"(3) in the case of a defoliant, an ingredient which will cause the leaves or foliage to drop from a plant;"],[1,"(4) in the case of a desiccant, an ingredient which will artificially accelerate the drying of plant tissue; and"],[1,"(5) in the case of a nitrogen stabilizer, an ingredient which will prevent or hinder the process of nitrification, denitrification, ammonia volatilization, or urease production through action affecting soil bacteria."],[0,"(b) Administrator"],[0,"The term \"Administrator\" means the Administrator of the Environmental Protection Agency."],[0,"(c) Adulterated"],[0,"The term \"adulterated\" applies to any pesticide if—"],[1,"(1) its strength or purity falls below the professed standard of quality as expressed on its labeling under which it is sold;"],[1,"(2) any substance has been substituted wholly or in part for the pesticide; or"],[1,"(3) any valuable constituent of the pesticide has been wholly or in part abstracted."],[0,"(d) Animal"],[0,"The term \"animal\" means all vertebrate and invertebrate species, including but not limited to man and other mammals, birds, fish, and shellfish."],[0,"(e) Certified applicator, etc."],[0,"(1) Certified applicator"],[1,"The term \"certified applicator\" means any individual who is certified under section 136i of this title as authorized to use or supervise the use of any pesticide which is classified for restricted use. Any applicator who holds or applies registered pesticides, or uses dilutions of registered pesticides consistent with subsection (ee), only to provide a service of controlling pests without delivering any unapplied pesticide to any person so served is not deemed to be a seller or distributor of pesticides under this subchapter."],[0,"(2) Private applicator"],[1,"The term \"private applicator\" means a certified applicator who uses or supervises the use of any pesticide which is classified for restricted use for purposes of producing any agricultural commodity on property owned or rented by the applicator or the applicator's employer or (if applied without compensation other than trading of personal services between producers of agricultural commodities) on the property of another person."],[0,"(3) Commercial applicator"],[1,"The term \"commercial applicator\" means an applicator (whether or not the applicator is a private applicator with respect to some uses) who uses or supervises the use of any pesticide which is classified for restricted use for any purpose or on any property other than as provided by paragraph (2)."],[0,"(4) Under the direct supervision of a certified applicator"],[1,"Unless otherwise prescribed by its labeling, a pesticide shall be considered to be applied under the direct supervision of a certified applicator if it is applied by a competent person acting under the instructions and control of a certified applicator who is available if and when needed, even though such certified applicator is not physically present at the time and place the pesticide is applied."],[0,"(f) Defoliant"],[0,"The term \"defoliant\" means any substance or mixture of substances intended for causing the leaves or foliage to drop from a plant, with or without causing abscission."],[0,"(g) Desiccant"],[0,"The term \"desiccant\" means any substance or mixture of substances intended for artificially accelerating the drying of plant tissue."],[0,"(h) Device"],[0,"The term \"device\" means any instrument or contrivance (other than a firearm) which is intended for trapping, destroying, repelling, or mitigating any pest or any other form of plant or animal life (other than man and other than bacteria, virus, or other microorganism on or in living man or other living animals); but not including equipment used for the application of pesticides when sold separately therefrom."],[0,"(i) District court"],[0,"The term \"district court\" means a United States district court, the District Court of Guam, the District Court of the Virgin Islands, and the highest court of American Samoa."],[0,"(j) Environment"],[0,"The term \"environment\" includes water, air, land, and all plants and man and other animals living therein, and the interrelationships which exist among these."],[0,"(k) Fungus"],[0,"The term \"fungus\" means any non-chlorophyll-bearing thallophyte (that is, any non-chlorophyll-bearing plant of a lower order than mosses and liverworts), as for example, rust, smut, mildew, mold, yeast, and bacteria, except those on or in living man or other animals and those on or in processed food, beverages, or pharmaceuticals."],[0,"(l) Imminent hazard"],[0,"The term \"imminent hazard\" means a situation which exists when the continued use of a pesticide during the time required for cancellation proceeding would be likely to result in unreasonable adverse effects on the environment or will involve unreasonable hazard to the survival of a species declared endangered or threatened by the Secretary pursuant to the Endangered Species Act of 1973 [16 U.S.C. 1531 et seq.]."],[0,"(m) Inert ingredient"],[0,"The term \"inert ingredient\" means an ingredient which is not active."],[0,"(n) Ingredient statement"],[0,"The term \"ingredient statement\" means a statement which contains—"],[1,"(1) the name and percentage of each active ingredient, and the total percentage of all inert ingredients, in the pesticide; and"],[1,"(2) if the pesticide contains arsenic in any form, a statement of the percentages of total and water soluble arsenic, calculated as elementary arsenic."],[0,"(o) Insect"],[0,"The term \"insect\" means any of the numerous small invertebrate animals generally having the body more or less obviously segmented, for the most part belonging to the class insecta, comprising six-legged, usually winged forms, as for example, beetles, bugs, bees, flies, and to other allied classes of arthropods whose members are wingless and usually have more than six legs, as for example, spiders, mites, ticks, centipedes, and wood lice."],[0,"(p) Label and labeling"],[0,"(1) Label"],[1,"The term \"label\" means the written, printed, or graphic matter on, or attached to, the pesticide or device or any of its containers or wrappers."],[0,"(2) Labeling"],[1,"The term \"labeling\" means all labels and all other written, printed, or graphic matter—"],[2,"(A) accompanying the pesticide or device at any time; or"],[2,"(B) to which reference is made on the label or in literature accompanying the pesticide or device, except to current official publications of the Environmental Protection Agency, the United States Departments of Agriculture and Interior, the Department of Health and Human Services, State experiment stations, State agricultural colleges, and other similar Federal or State institutions or agencies authorized by law to conduct research in the field of pesticides."],[0,"(q) Misbranded"],[1,"(1) A pesticide is misbranded if—"],[2,"(A) its labeling bears any statement, design, or graphic representation relative thereto or to its ingredients which is false or misleading in any particular;"],[2,"(B) it is contained in a package or other container or wrapping which does not conform to the standards established by the Administrator pursuant to section 136w(c)(3) of this title;"],[2,"(C) it is an imitation of, or is offered for sale under the name of, another pesticide;"],[2,"(D) its label does not bear the registration number assigned under section 136e of this title to each establishment in which it was produced;"],[2,"(E) any word, statement, or other information required by or under authority of this subchapter to appear on the label or labeling is not prominently placed thereon with such conspicuousness (as compared with other words, statements, designs, or graphic matter in the labeling) and in such terms as to render it likely to be read and understood by the ordinary individual under customary conditions of purchase and use;"],[2,"(F) the labeling accompanying it does not contain directions for use which are necessary for effecting the purpose for which the product is intended and if complied with, together with any requirements imposed under section 136a(d) of this title, are adequate to protect health and the environment;"],[2,"(G) the label does not contain a warning or caution statement which may be necessary and if complied with, together with any requirements imposed under section 136a(d) of this title, is adequate to protect health and the environment; or"],[2,"(H) in the case of a pesticide not registered in accordance with section 136a of this title and intended for export, the label does not contain, in words prominently placed thereon with such conspicuousness (as compared with other words, statements, designs, or graphic matter in the labeling) as to render it likely to be noted by the ordinary individual under customary conditions of purchase and use, the following: \"Not Registered for Use in the United States of America\"."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§136. Definitions","tname":"Agriculture","by":{"0":"7, 23, 33, 36, 38, 41, 28, 27, 4, 7, 23, 41, 7, 23, 41, 50","1":"1-6, 8, 11-15, 18, 19, 22, 23, 25-28, 31, 32, 6, 21, 35, 19, 19, 2, 3, 6, 12, 17, 19, 23-25, 2, 6, 17, 1, 2, 6, 17, 24, 25, 34","2":"29, 51, 9, 2, 4, 10, 13, 18, 19, 20, 33, 39, 40, 2, 4, 10, 13, 18, 40","4":"13, 21, 10, 13, 21, 12, 13, 21"}},{"t":"usc","label":"7 U.S.C. § 136a","url":"https://www.law.cornell.edu/uscode/text/7/136a","subs":["(a)","(c)","(c)(2)","(c)(5)","(f)(2)","(g)(1)","(c)(1)(C)","(c)(1)(D)","(c)(1)(F)","(c)(5)(B)","(c)(5)(D)","(c)(7)(A)","(g)(1)(A)(iii)(II)","(g)(1)(A)(iv)","(c)(3)(A)","(c)(5)(A)","(c)(6)","(f)(1)"],"stext":{"head":"§136a. Registration of pesticides","paras":[[0,"(a) Requirement of registration"],[0,"Except as provided by this subchapter, no person in any State may distribute or sell to any person any pesticide that is not registered under this subchapter. To the extent necessary to prevent unreasonable adverse effects on the environment, the Administrator may by regulation limit the distribution, sale, or use in any State of any pesticide that is not registered under this subchapter and that is not the subject of an experimental use permit under section 136c of this title or an emergency exemption under section 136p of this title."],[0,"(b) Exemptions"],[0,"A pesticide which is not registered with the Administrator may be transferred if—"],[1,"(1) the transfer is from one registered establishment to another registered establishment operated by the same producer solely for packaging at the second establishment or for use as a constituent part of another pesticide produced at the second establishment; or"],[1,"(2) the transfer is pursuant to and in accordance with the requirements of an experimental use permit."],[0,"(c) Procedure for registration"],[0,"(1) Statement required"],[1,"Each applicant for registration of a pesticide shall file with the Administrator a statement which includes—"],[2,"(A) the name and address of the applicant and of any other person whose name will appear on the labeling;"],[2,"(B) the name of the pesticide;"],[2,"(C) a complete copy of the labeling of the pesticide, a statement of all claims to be made for it, and any directions for its use;"],[2,"(D) the complete formula of the pesticide;"],[2,"(E) a request that the pesticide be classified for general use or for restricted use, or for both; and"],[2,"(F) except as otherwise provided in paragraph (2)(D), if requested by the Administrator, a full description of the tests made and the results thereof upon which the claims are based, or alternatively a citation to data that appear in the public literature or that previously had been submitted to the Administrator and that the Administrator may consider in accordance with the following provisions:"],[3,"(i) With respect to pesticides containing active ingredients that are initially registered under this subchapter after September 30, 1978, data submitted to support the application for the original registration of the pesticide, or an application for an amendment adding any new use to the registration and that pertains solely to such new use, shall not, without the written permission of the original data submitter, be considered by the Administrator to support an application by another person during a period of ten years following the date the Administrator first registers the pesticide, except that such permission shall not be required in the case of defensive data."],[3,"(ii) The period of exclusive data use provided under clause (i) shall be extended 1 additional year for each 3 minor uses registered after August 3, 1996, and within 7 years of the commencement of the exclusive use period, up to a total of 3 additional years for all minor uses registered by the Administrator if the Administrator, in consultation with the Secretary of Agriculture, determines that, based on information provided by an applicant for registration or a registrant, that—"],[4,"(I) there are insufficient efficacious alternative registered pesticides available for the use;"],[4,"(II) the alternatives to the minor use pesticide pose greater risks to the environment or human health;"],[4,"(III) the minor use pesticide plays or will play a significant part in managing pest resistance; or"],[4,"(IV) the minor use pesticide plays or will play a significant part in an integrated pest management program."],[0,"The registration of a pesticide for a minor use on a crop grouping established by the Administrator shall be considered for purposes of this clause 1 minor use for each representative crop for which data are provided in the crop grouping. Any additional exclusive use period under this clause shall be modified as appropriate or terminated if the registrant voluntarily cancels the product or deletes from the registration the minor uses which formed the basis for the extension of the additional exclusive use period or if the Administrator determines that the registrant is not actually marketing the product for such minor uses."],[3,"(iii) Except as otherwise provided in clause (i), with respect to data submitted after December 31, 1969, by an applicant or registrant to support an application for registration, experimental use permit, or amendment adding a new use to an existing registration, to support or maintain in effect an existing registration, or for reregistration, the Administrator may, without the permission of the original data submitter, consider any such item of data in support of an application by any other person (hereinafter in this subparagraph referred to as the \"applicant\") within the fifteen-year period following the date the data were originally submitted only if the applicant has made an offer to compensate the original data submitter and submitted such offer to the Administrator accompanied by evidence of delivery to the original data submitter of the offer. The terms and amount of compensation may be fixed by agreement between the original data submitter and the applicant, or, failing such agreement, binding arbitration under this subparagraph. If, at the end of ninety days after the date of delivery to the original data submitter of the offer to compensate, the original data submitter and the applicant have neither agreed on the amount and terms of compensation nor on a procedure for reaching an agreement on the amount and terms of compensation, either person may initiate binding arbitration proceedings by requesting the Federal Mediation and Conciliation Service to appoint an arbitrator from the roster of arbitrators maintained by such Service. The procedure and rules of the Service shall be applicable to the selection of such arbitrator and to such arbitration proceedings, and the findings and determination of the arbitrator shall be final and conclusive, and no official or court of the United States shall have power or jurisdiction to review any such findings and determination, except for fraud, misrepresentation, or other misconduct by one of the parties to the arbitration or the arbitrator where there is a verified complaint with supporting affidavits attesting to specific instances of such fraud, misrepresentation, or other misconduct. The parties to the arbitration shall share equally in the payment of the fee and expenses of the arbitrator. If the Administrator determines that an original data submitter has failed to participate in a procedure for reaching an agreement or in an arbitration proceeding as required by this subparagraph, or failed to comply with the terms of an agreement or arbitration decision concerning compensation under this subparagraph, the original data submitter shall forfeit the right to compensation for the use of the data in support of the application. Notwithstanding any other provision of this subchapter, if the Administrator determines that an applicant has failed to participate in a procedure for reaching an agreement or in an arbitration proceeding as required by this subparagraph, or failed to comply with the terms of an agreement or arbitration decision concerning compensation under this subparagraph, the Administrator shall deny the application or cancel the registration of the pesticide in support of which the data were used without further hearing. Before the Administrator takes action under either of the preceding two sentences, the Administrator shall furnish to the affected person, by certified mail, notice of intent to take action and allow fifteen days from the date of delivery of the notice for the affected person to respond. If a registration is denied or canceled under this subparagraph, the Administrator may make such order as the Administrator deems appropriate concerning the continued sale and use of existing stocks of such pesticide. Registration action by the Administrator shall not be delayed pending the fixing of compensation."],[3,"(iv) After expiration of any period of exclusive use and any period for which compensation is required for the use of an item of data under clauses (i), (ii), and (iii), the Administrator may consider such item of data in support of an application by any other applicant without the permission of the original data submitter and without an offer having been received to compensate the original data submitter for the use of such item of data."],[3,"(v) The period of exclusive use provided under clause (ii) shall not take effect until 1 year after August 3, 1996, except where an applicant or registrant is applying for the registration of a pesticide containing an active ingredient not previously registered."],[3,"(vi) With respect to data submitted after August 3, 1996, by an applicant or registrant to support an amendment adding a new use to an existing registration that does not retain any period of exclusive use, if such data relates solely to a minor use of a pesticide, such data shall not, without the written permission of the original data submitter, be considered by the Administrator to support an application for a minor use by another person during the period of 10 years following the date of submission of such data. The applicant or registrant at the time the new minor use is requested shall notify the Administrator that to the best of their knowledge the exclusive use period for the pesticide has expired and that the data pertaining solely to the minor use of a pesticide is eligible for the provisions of this paragraph. If the minor use registration which is supported by data submitted pursuant to this subsection is voluntarily canceled or if such data are subsequently used to support a nonminor use, the data shall no longer be subject to the exclusive use provisions of this clause but shall instead be considered by the Administrator in accordance with the provisions of clause (i), as appropriate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136a?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§136a. Registration of pesticides","tname":"Agriculture","by":{"0":"7, 45, 8, 24, 7, 23, 33, 38, 39, 8, 9, 38","1":"20, 5, 20, 5, 6, 5, 5, 5, 19, 2, 6, 19, 1, 19, 34, 1, 6, 22, 13, 25-27, 7, 7","2":"8, 8, 11, 19, 38, 8, 8, 22, 2, i, 8, 10, 23, 2, 9, i, 6, 9, 10, 11, 17, 28, 30, 32","3":"18, 7","4":"12, 10, 20, 20, 21, 14"}},{"t":"usc","label":"7 U.S.C. § 136a-1","url":"https://www.law.cornell.edu/uscode/text/7/136a-1","subs":["(b)(5)","(d)(3)","(g)","(m)"],"stext":{"head":"§136a–1. Reregistration of registered pesticides","paras":[[0,"(a) General rule"],[0,"The Administrator shall reregister, in accordance with this section, each registered pesticide containing any active ingredient contained in any pesticide first registered before November 1, 1984, except for any pesticide as to which the Administrator has determined, after November 1, 1984, and before the effective date of this section, that—"],[1,"(1) there are no outstanding data requirements; and"],[1,"(2) the requirements of section 136a(c)(5) of this title have been satisfied."],[0,"(b) Reregistration phases"],[0,"Reregistrations of pesticides under this section shall be carried out in the following phases:"],[1,"(1) The first phase shall include the listing under subsection (c) of the active ingredients of the pesticides that will be reregistered."],[1,"(2) The second phase shall include the submission to the Administrator under subsection (d) of notices by registrants respecting their intention to seek reregistration, identification by registrants of missing and inadequate data for such pesticides, and commitments by registrants to replace such missing or inadequate data within the applicable time period."],[1,"(3) The third phase shall include submission to the Administrator by registrants of the information required under subsection (e)."],[1,"(4) The fourth phase shall include an independent, initial review by the Administrator under subsection (f) of submissions under phases two and three, identification of outstanding data requirements, and the issuance, as necessary, of requests for additional data."],[1,"(5) The fifth phase shall include the review by the Administrator under subsection (g) of data submitted for reregistration and appropriate regulatory action by the Administrator."],[0,"(c) Phase one"],[0,"(1) Priority for reregistration"],[1,"For purposes of the reregistration of the pesticides described in subsection (a), the Administrator shall list the active ingredients of pesticides and shall give priority to, among others, active ingredients (other than active ingredients for which registration standards have been issued before the effective date of this section) that—"],[2,"(A) are in use on or in food or feed and may result in postharvest residues;"],[2,"(B) may result in residues of potential toxicological concern in potable ground water, edible fish, or shellfish;"],[2,"(C) have been determined by the Administrator before the effective date of this section to have significant outstanding data requirements; or"],[2,"(D) are used on crops, including in greenhouses and nurseries, where worker exposure is most likely to occur."],[0,"(2) Reregistration lists"],[1,"For purposes of reregistration under this section, the Administrator shall by order—"],[2,"(A) not later than 70 days after the effective date of this section, list pesticide active ingredients for which registration standards have been issued before such effective date;"],[2,"(B) not later than 4 months after such effective date, list the first 150 pesticide active ingredients, as determined under paragraph (1);"],[2,"(C) not later than 7 months after such effective date, list the second 150 pesticide active ingredients, as determined under paragraph (1); and"],[2,"(D) not later than 10 months after such effective date, list the remainder of the pesticide active ingredients, as determined under paragraph (1)."],[1,"Each list shall be published in the Federal Register."],[0,"(3) Judicial review"],[1,"The content of a list issued by the Administrator under paragraph (2) shall not be subject to judicial review."],[0,"(4) Notice to registrants"],[1,"On the publication of a list of pesticide active ingredients under paragraph (2), the Administrator shall send by certified mail to the registrants of the pesticides containing such active ingredients a notice of the time by which the registrants are to notify the Administrator under subsection (d) whether the registrants intend to seek or not to seek reregistration of such pesticides."],[0,"(d) Phase two"],[0,"(1) In general"],[1,"The registrant of a pesticide that contains an active ingredient listed under subparagraph (B), (C), or (D) of subsection (c)(2) shall submit to the Administrator, within the time period prescribed by paragraph (4), the notice described in paragraph (2) and any information, commitment, or offer described in paragraph (3)."],[0,"(2) Notice of intent to seek or not to seek reregistration"],[1,"(A) The registrant of a pesticide containing an active ingredient listed under subparagraph (B), (C), or (D) of subsection (c)(2) shall notify the Administrator by certified mail whether the registrant intends to seek or does not intend to seek reregistration of the pesticide."],[1,"(B) If a registrant submits a notice under subparagraph (A) of an intention not to seek reregistration of a pesticide, the Administrator shall publish a notice in the Federal Register stating that such a notice has been submitted."],[0,"(3) Missing or inadequate data"],[1,"Each registrant of a pesticide that contains an active ingredient listed under subparagraph (B), (C), or (D) of subsection (c)(2) and for which the registrant submitted a notice under paragraph (2) of an intention to seek reregistration of such pesticide shall submit to the Administrator—"],[2,"(A) in accordance with regulations issued by the Administrator under section 136a of this title, an identification of—"],[3,"(i) all data that are required by regulation to support the registration of the pesticide with respect to such active ingredient;"],[3,"(ii) data that were submitted by the registrant previously in support of the registration of the pesticide that are inadequate to meet such regulations; and"],[3,"(iii) data identified under clause (i) that have not been submitted to the Administrator; and"],[2,"(B) either—"],[3,"(i) a commitment to replace the data identified under subparagraph (A)(ii) and submit the data identified under subparagraph (A)(iii) within the applicable time period prescribed by paragraph (4)(B); or"],[3,"(ii) an offer to share in the cost to be incurred by a person who has made a commitment under clause (i) to replace or submit the data and an offer to submit to arbitration as described by section 136a(c)(2)(B) of this title with regard to such cost sharing."],[1,"For purposes of a submission by a registrant under subparagraph (A)(ii), data are inadequate if the data are derived from a study with respect to which the registrant is unable to make the certification prescribed by subsection (e)(1)(G) that the registrant possesses or has access to the raw data used in or generated by such study. For purposes of a submission by a registrant under such subparagraph, data shall be considered to be inadequate if the data are derived from a study submitted before January 1, 1970, unless it is demonstrated to the satisfaction of the Administrator that such data should be considered to support the registration of the pesticide that is to be reregistered."],[0,"(4) Time periods"],[1,"(A) A submission under paragraph (2) or (3) shall be made—"],[2,"(i) in the case of a pesticide containing an active ingredient listed under subsection (c)(2)(B), not later than 3 months after the date of publication of the listing of such active ingredient;"],[2,"(ii) in the case of a pesticide containing an active ingredient listed under subsection (c)(2)(C), not later than 3 months after the date of publication of the listing of such active ingredient; and"],[2,"(iii) in the case of a pesticide containing an active ingredient listed under subsection (c)(2)(D), not later than 3 months after the date of publication of the listing of such active ingredient."],[1,"On application, the Administrator may extend a time period prescribed by this subparagraph if the Administrator determines that factors beyond the control of the registrant prevent the registrant from complying with such period."],[1,"(B) A registrant shall submit data in accordance with a commitment entered into under paragraph (3)(B) within a reasonable period of time, as determined by the Administrator, but not more than 48 months after the date the registrant submitted the commitment. The Administrator, on application of a registrant, may extend the period prescribed by the preceding sentence by no more than 2 years if extraordinary circumstances beyond the control of the registrant prevent the registrant from submitting data within such prescribed period. Upon application of a registrant, the Administrator shall, in the case of a minor use, extend the deadline for the production of residue chemistry data under this subparagraph for data required solely to support that minor use until the final deadline for submission of data under this section for the other uses of the pesticide established as of August 3, 1996, if—"],[2,"(i) the data to support other uses of the pesticide on a food are being provided;"],[2,"(ii) the registrant, in submitting a request for such an extension provides a schedule, including interim dates to measure progress, to assure that the data production will be completed before the expiration of the extension period;"],[2,"(iii) the Administrator has determined that such extension will not significantly delay the Administrator's schedule for issuing a reregistration eligibility determination required under this section; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136a-1?type=usc&year=mostrecent&link-type=html"},"head":"§136a–1. Reregistration of registered pesticides","tname":"Agriculture","by":{"0":"49, 31, 27, 8","1":"7"}},{"t":"usc","label":"7 U.S.C. § 136d","url":"https://www.law.cornell.edu/uscode/text/7/136d","subs":["(a)(2)","(b)","(2)"],"stext":{"head":"§136d. Administrative review; suspension","paras":[[0,"(a) Existing stocks and information"],[0,"(1) Existing stocks"],[1,"The Administrator may permit the continued sale and use of existing stocks of a pesticide whose registration is suspended or canceled under this section, or section 136a or 136a–1 of this title, to such extent, under such conditions, and for such uses as the Administrator determines that such sale or use is not inconsistent with the purposes of this subchapter."],[0,"(2) Information"],[1,"If at any time after the registration of a pesticide the registrant has additional factual information regarding unreasonable adverse effects on the environment of the pesticide, the registrant shall submit such information to the Administrator."],[0,"(b) Cancellation and change in classification"],[0,"If it appears to the Administrator that a pesticide or its labeling or other material required to be submitted does not comply with the provisions of this subchapter or, when used in accordance with widespread and commonly recognized practice, generally causes unreasonable adverse effects on the environment, the Administrator may issue a notice of the Administrator's intent either—"],[1,"(1) to cancel its registration or to change its classification together with the reasons (including the factual basis) for the Administrator's action, or"],[1,"(2) to hold a hearing to determine whether or not its registration should be canceled or its classification changed."],[0,"Such notice shall be sent to the registrant and made public. In determining whether to issue any such notice, the Administrator shall include among those factors to be taken into account the impact of the action proposed in such notice on production and prices of agricultural commodities, retail food prices, and otherwise on the agricultural economy. At least 60 days prior to sending such notice to the registrant or making public such notice, whichever occurs first, the Administrator shall provide the Secretary of Agriculture with a copy of such notice and an analysis of such impact on the agricultural economy. If the Secretary comments in writing to the Administrator regarding the notice and analysis within 30 days after receiving them, the Administrator shall publish in the Federal Register (with the notice) the comments of the Secretary and the response of the Administrator with regard to the Secretary's comments. If the Secretary does not comment in writing to the Administrator regarding the notice and analysis within 30 days after receiving them, the Administrator may notify the registrant and make public the notice at any time after such 30-day period notwithstanding the foregoing 60-day time requirement. The time requirements imposed by the preceding 3 sentences may be waived or modified to the extent agreed upon by the Administrator and the Secretary. Notwithstanding any other provision of this subsection and section 136w(d) of this title, in the event that the Administrator determines that suspension of a pesticide registration is necessary to prevent an imminent hazard to human health, then upon such a finding the Administrator may waive the requirement of notice to and consultation with the Secretary of Agriculture pursuant to this subsection and of submission to the Scientific Advisory Panel pursuant to section 136w(d) of this title and proceed in accordance with subsection (c). When a public health use is affected, the Secretary of Health and Human Services should provide available benefits and use information, or an analysis thereof, in accordance with the procedures followed and subject to the same conditions as the Secretary of Agriculture in the case of agricultural pesticides. The proposed action shall become final and effective at the end of 30 days from receipt by the registrant, or publication, of a notice issued under paragraph (1), whichever occurs later, unless within that time either (i) the registrant makes the necessary corrections, if possible, or (ii) a request for a hearing is made by a person adversely affected by the notice. In the event a hearing is held pursuant to such a request or to the Administrator's determination under paragraph (2), a decision pertaining to registration or classification issued after completion of such hearing shall be final. In taking any final action under this subsection, the Administrator shall consider restricting a pesticide's use or uses as an alternative to cancellation and shall fully explain the reasons for these restrictions, and shall include among those factors to be taken into account the impact of such final action on production and prices of agricultural commodities, retail food prices, and otherwise on the agricultural economy, and the Administrator shall publish in the Federal Register an analysis of such impact."],[0,"(c) Suspension"],[0,"(1) Order"],[1,"If the Administrator determines that action is necessary to prevent an imminent hazard during the time required for cancellation or change in classification proceedings, the Administrator may, by order, suspend the registration of the pesticide immediately. Except as provided in paragraph (3), no order of suspension may be issued under this subsection unless the Administrator has issued, or at the same time issues, a notice of intention to cancel the registration or change the classification of the pesticide under subsection (b). Except as provided in paragraph (3), the Administrator shall notify the registrant prior to issuing any suspension order. Such notice shall include findings pertaining to the question of \"imminent hazard\". The registrant shall then have an opportunity, in accordance with the provisions of paragraph (2), for an expedited hearing before the Administrator on the question of whether an imminent hazard exists."],[0,"(2) Expedite hearing"],[1,"If no request for a hearing is submitted to the Administrator within five days of the registrant's receipt of the notification provided for by paragraph (1), the suspension order may be issued and shall take effect and shall not be reviewable by a court. If a hearing is requested, it shall commence within five days of the receipt of the request for such hearing unless the registrant and the Administrator agree that it shall commence at a later time. The hearing shall be held in accordance with the provisions of subchapter II of chapter 5 of title 5, except that the presiding officer need not be a certified administrative law judge. The presiding officer shall have ten days from the conclusion of the presentation of evidence to submit recommended findings and conclusions to the Administrator, who shall then have seven days to render a final order on the issue of suspension."],[0,"(3) Emergency order"],[1,"Whenever the Administrator determines that an emergency exists that does not permit the Administrator to hold a hearing before suspending, the Administrator may issue a suspension order in advance of notification to the registrant. The Administrator may issue an emergency order under this paragraph before issuing a notice of intention to cancel the registration or change the classification of the pesticide under subsection (b) and the Administrator shall proceed to issue the notice under subsection (b) within 90 days of issuing an emergency order. If the Administrator does not issue a notice under subsection (b) within 90 days of issuing an emergency order, the emergency order shall expire. In the case of an emergency order, paragraph (2) shall apply except that (A) the order of suspension shall be in effect pending the expeditious completion of the remedies provided by that paragraph and the issuance of a final order on suspension, and (B) no party other than the registrant and the Administrator shall participate except that any person adversely affected may file briefs within the time allotted by the Agency's rules. Any person so filing briefs shall be considered a party to such proceeding for the purposes of section 136n(b) of this title."],[0,"(4) Judicial review"],[1,"A final order on the question of suspension following a hearing shall be reviewable in accordance with section 136n of this title, notwithstanding the fact that any related cancellation proceedings have not been completed. Any order of suspension entered prior to a hearing before the Administrator shall be subject to immediate review in an action by the registrant or other interested person with the concurrence of the registrant in an appropriate district court, solely to determine whether the order of suspension was arbitrary, capricious or an abuse of discretion, or whether the order was issued in accordance with the procedures established by law. The effect of any order of the court will be only to stay the effectiveness of the suspension order, pending the Administrator's final decision with respect to cancellation or change in classification. This action may be maintained simultaneously with any administrative review proceedings under this section. The commencement of proceedings under this paragraph shall not operate as a stay of order, unless ordered by the court."],[0,"(d) Public hearings and scientific review"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136d?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§136d. Administrative review; suspension","tname":"Agriculture","by":{"0":"9, 26, 38, 9, 26","1":"7, 26, 7, 19, 21","2":"2, 2","3":"19, 18","4":"11, 13"}},{"t":"usc","label":"7 U.S.C. § 136h","url":"https://www.law.cornell.edu/uscode/text/7/136h","subs":["(a)"],"by":{"0":"27"}},{"t":"usc","label":"7 U.S.C. § 136j","url":"https://www.law.cornell.edu/uscode/text/7/136j","subs":["(a)(1)","(a)(2)","(a)(1)(A)","(a)(1)(B)","(a)(1)(C)","(a)(1)(E)","(a)(2)(F)","(a)(2)(G)"],"stext":{"head":"§136j. Unlawful acts","paras":[[0,"(a) In general"],[0,"(1) Except as provided by subsection (b), it shall be unlawful for any person in any State to distribute or sell to any person—"],[1,"(A) any pesticide that is not registered under section 136a of this title or whose registration has been canceled or suspended, except to the extent that distribution or sale otherwise has been authorized by the Administrator under this subchapter;"],[1,"(B) any registered pesticide if any claims made for it as a part of its distribution or sale substantially differ from any claims made for it as a part of the statement required in connection with its registration under section 136a of this title;"],[1,"(C) any registered pesticide the composition of which differs at the time of its distribution or sale from its composition as described in the statement required in connection with its registration under section 136a of this title;"],[1,"(D) any pesticide which has not been colored or discolored pursuant to the provisions of section 136w(c)(5) of this title;"],[1,"(E) any pesticide which is adulterated or misbranded; or"],[1,"(F) any device which is misbranded."],[0,"(2) It shall be unlawful for any person—"],[1,"(A) to detach, alter, deface, or destroy, in whole or in part, any labeling required under this subchapter;"],[1,"(B) to refuse to—"],[2,"(i) prepare, maintain, or submit any records required by or under section 136c, 136e, 136f, 136i, or 136q of this title;"],[2,"(ii) submit any reports required by or under section 136c, 136d, 136e, 136f, 136i, or 136q of this title; or"],[2,"(iii) allow any entry, inspection, copying of records, or sampling authorized by this subchapter;"],[1,"(C) to give a guaranty or undertaking provided for in subsection (b) which is false in any particular, except that a person who receives and relies upon a guaranty authorized under subsection (b) may give a guaranty to the same effect, which guaranty shall contain, in addition to the person's own name and address, the name and address of the person residing in the United States from whom the person received the guaranty or undertaking;"],[1,"(D) to use for the person's own advantage or to reveal, other than to the Administrator, or officials or employees of the Environmental Protection Agency or other Federal executive agencies, or to the courts, or to physicians, pharmacists, and other qualified persons, needing such information for the performance of their duties, in accordance with such directions as the Administrator may prescribe, any information acquired by authority of this subchapter which is confidential under this subchapter;"],[1,"(E) who is a registrant, wholesaler, dealer, retailer, or other distributor to advertise a product registered under this subchapter for restricted use without giving the classification of the product assigned to it under section 136a of this title;"],[1,"(F) to distribute or sell, or to make available for use, or to use, any registered pesticide classified for restricted use for some or all purposes other than in accordance with section 136a(d) of this title and any regulations thereunder, except that it shall not be unlawful to sell, under regulations issued by the Administrator, a restricted use pesticide to a person who is not a certified applicator for application by a certified applicator;"],[1,"(G) to use any registered pesticide in a manner inconsistent with its labeling;"],[1,"(H) to use any pesticide which is under an experimental use permit contrary to the provisions of such permit;"],[1,"(I) to violate any order issued under section 136k of this title;"],[1,"(J) to violate any suspension order issued under section 136a(c)(2)(B), 136a–1, or 136d of this title;"],[1,"(K) to violate any cancellation order issued under this subchapter or to fail to submit a notice in accordance with section 136d(g) of this title;"],[1,"(L) who is a producer to violate any of the provisions of section 136e of this title;"],[1,"(M) to knowingly falsify all or part of any application for registration, application for experimental use permit, any information submitted to the Administrator pursuant to section 136e of this title, any records required to be maintained pursuant to this subchapter, any report filed under this subchapter, or any information marked as confidential and submitted to the Administrator under any provision of this subchapter;"],[1,"(N) who is a registrant, wholesaler, dealer, retailer, or other distributor to fail to file reports required by this subchapter;"],[1,"(O) to add any substance to, or take any substance from, any pesticide in a manner that may defeat the purpose of this subchapter;"],[1,"(P) to use any pesticide in tests on human beings unless such human beings (i) are fully informed of the nature and purposes of the test and of any physical and mental health consequences which are reasonably foreseeable therefrom, and (ii) freely volunteer to participate in the test;"],[1,"(Q) to falsify all or part of any information relating to the testing of any pesticide (or any ingredient, metabolite, or degradation product thereof), including the nature of any protocol, procedure, substance, organism, or equipment used, observation made, or conclusion or opinion formed, submitted to the Administrator, or that the person knows will be furnished to the Administrator or will become a part of any records required to be maintained by this subchapter;"],[1,"(R) to submit to the Administrator data known to be false in support of a registration; or"],[1,"(S) to violate any regulation issued under section 136a(a) or 136q of this title."],[0,"(b) Exemptions"],[0,"The penalties provided for a violation of paragraph (1) of subsection (a) shall not apply to—"],[1,"(1) any person who establishes a guaranty signed by, and containing the name and address of, the registrant or person residing in the United States from whom the person purchased or received in good faith the pesticide in the same unbroken package, to the effect that the pesticide was lawfully registered at the time of sale and delivery to the person, and that it complies with the other requirements of this subchapter, and in such case the guarantor shall be subject to the penalties which would otherwise attach to the person holding the guaranty under the provisions of this subchapter;"],[1,"(2) any carrier while lawfully shipping, transporting, or delivering for shipment any pesticide or device, if such carrier upon request of any officer or employee duly designated by the Administrator shall permit such officer or employee to copy all of its records concerning such pesticide or device;"],[1,"(3) any public official while engaged in the performance of the official duties of the public official;"],[1,"(4) any person using or possessing any pesticide as provided by an experimental use permit in effect with respect to such pesticide and such use or possession; or"],[1,"(5) any person who ships a substance or mixture of substances being put through tests in which the purpose is only to determine its value for pesticide purposes or to determine its toxicity or other properties and from which the user does not expect to receive any benefit in pest control from its use."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136j?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§136j. Unlawful acts","tname":"Agriculture","by":{"0":"9, 21, 25, 30, 45, 27, 28","1":"5, 5, 20, 5, 20, 6, 17, 20, 5, 20","2":"33, i, 2, 7, 9, 1, 11, 18, 29, 38, 39, 2, 30, i, 2, 8, 9, 19, 21, 29, 44","4":"14"}},{"t":"usc","label":"7 U.S.C. § 136k","url":"https://www.law.cornell.edu/uscode/text/7/136k","subs":["(b)","(a)","(c)"],"stext":{"head":"§136k. Stop sale, use, removal, and seizure","paras":[[0,"(a) Stop sale, etc., orders"],[0,"Whenever any pesticide or device is found by the Administrator in any State and there is reason to believe on the basis of inspection or tests that such pesticide or device is in violation of any of the provisions of this subchapter, or that such pesticide or device has been or is intended to be distributed or sold in violation of any such provisions, or when the registration of the pesticide has been canceled by a final order or has been suspended, the Administrator may issue a written or printed \"stop sale, use, or removal\" order to any person who owns, controls, or has custody of such pesticide or device, and after receipt of such order no person shall sell, use, or remove the pesticide or device described in the order except in accordance with the provisions of the order."],[0,"(b) Seizure"],[0,"Any pesticide or device that is being transported or, having been transported, remains unsold or in original unbroken packages, or that is sold or offered for sale in any State, or that is imported from a foreign country, shall be liable to be proceeded against in any district court in the district where it is found and seized for confiscation by a process in rem for condemnation if—"],[1,"(1) in the case of a pesticide—"],[2,"(A) it is adulterated or misbranded;"],[2,"(B) it is not registered pursuant to the provisions of section 136a of this title;"],[2,"(C) its labeling fails to bear the information required by this subchapter;"],[2,"(D) it is not colored or discolored and such coloring or discoloring is required under this subchapter; or"],[2,"(E) any of the claims made for it or any of the directions for its use differ in substance from the representations made in connection with its registration;"],[1,"(2) in the case of a device, it is misbranded; or"],[1,"(3) in the case of a pesticide or device, when used in accordance with the requirements imposed under this subchapter and as directed by the labeling, it nevertheless causes unreasonable adverse effects on the environment."],[0,"In the case of a plant regulator, defoliant, or desiccant, used in accordance with the label claims and recommendations, physical or physiological effects on plants or parts thereof shall not be deemed to be injury, when such effects are the purpose for which the plant regulator, defoliant, or desiccant was applied."],[0,"(c) Disposition after condemnation"],[0,"If the pesticide or device is condemned it shall, after entry of the decree, be disposed of by destruction or sale as the court may direct and the proceeds, if sold, less the court costs, shall be paid into the Treasury of the United States, but the pesticide or device shall not be sold contrary to the provisions of this subchapter or the laws of the jurisdiction in which it is sold. On payment of the costs of the condemnation proceedings and the execution and delivery of a good and sufficient bond conditioned that the pesticide or device shall not be sold or otherwise disposed of contrary to the provisions of the subchapter or the laws of any jurisdiction in which sold, the court may direct that such pesticide or device be delivered to the owner thereof. The proceedings of such condemnation cases shall conform, as near as may be to the proceedings in admiralty, except that either party may demand trial by jury of any issue of fact joined in any case, and all such proceedings shall be at the suit of and in the name of the United States."],[0,"(d) Court costs, etc."],[0,"When a decree of condemnation is entered against the pesticide or device, court costs and fees, storage, and other proper expenses shall be awarded against the person, if any, intervening as claimant of the pesticide or device."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136k?type=usc&year=mostrecent&link-type=html"},"head":"§136k. Stop sale, use, removal, and seizure","tname":"Agriculture","by":{"0":"27","1":"21, 5, 5","2":"31"}},{"t":"usc","label":"7 U.S.C. § 136v","url":"https://www.law.cornell.edu/uscode/text/7/136v","subs":["(a)","(b)","(c)(1)","(c)","(b)(2)"],"stext":{"head":"§136v. Authority of States","paras":[[0,"(a) In general"],[0,"A State may regulate the sale or use of any federally registered pesticide or device in the State, but only if and to the extent the regulation does not permit any sale or use prohibited by this subchapter."],[0,"(b) Uniformity"],[0,"Such State shall not impose or continue in effect any requirements for labeling or packaging in addition to or different from those required under this subchapter."],[0,"(c) Additional uses"],[0,"(1) A State may provide registration for additional uses of federally registered pesticides formulated for distribution and use within that State to meet special local needs in accord with the purposes of this subchapter and if registration for such use has not previously been denied, disapproved, or canceled by the Administrator. Such registration shall be deemed registration under section 136a of this title for all purposes of this subchapter, but shall authorize distribution and use only within such State."],[0,"(2) A registration issued by a State under this subsection shall not be effective for more than ninety days if disapproved by the Administrator within that period. Prior to disapproval, the Administrator shall, except as provided in paragraph (3) of this subsection, advise the State of the Administrator's intention to disapprove and the reasons therefor, and provide the State time to respond. The Administrator shall not prohibit or disapprove a registration issued by a State under this subsection (A) on the basis of lack of essentiality of a pesticide or (B) except as provided in paragraph (3) of this subsection, if its composition and use patterns are similar to those of a federally registered pesticide."],[0,"(3) In no instance may a State issue a registration for a food or feed use unless there exists a tolerance or exemption under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.] that permits the residues of the pesticides on the food or feed. If the Administrator determines that a registration issued by a State is inconsistent with the Federal Food, Drug, and Cosmetic Act, or the use of, a pesticide under a registration issued by a State constitutes an imminent hazard, the Administrator may immediately disapprove the registration."],[0,"(4) If the Administrator finds, in accordance with standards set forth in regulations issued under section 136w of this title, that a State is not capable of exercising adequate controls to assure that State registration under this section will be in accord with the purposes of this subchapter or has failed to exercise adequate controls, the Administrator may suspend the authority of the State to register pesticides until such time as the Administrator is satisfied that the State can and will exercise adequate controls. Prior to any such suspension, the Administrator shall advise the State of the Administrator's intention to suspend and the reasons therefor and provide the State time to respond."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136v?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§136v. Authority of States","tname":"Agriculture","by":{"0":"10, 1, 10, 20, 21, 23, 26, 27, 28, 34, 35, 10","1":"7, 8, 28, 35, 3, 4, 8, 11, 12, 14-17, 20, 28, 33, 35, 8","2":"i, 3, 12, 20, 21, 32, 36, 50, 13","3":"5, 10, 11, 4, 5, 10, 11","4":"1, 3"}},{"t":"usc","label":"7 U.S.C. § 136w","url":"https://www.law.cornell.edu/uscode/text/7/136w","subs":["(d)"],"stext":{"head":"§136w. Authority of Administrator","paras":[[0,"(a) In general"],[0,"(1) Regulations"],[1,"The Administrator is authorized, in accordance with the procedure described in paragraph (2), to prescribe regulations to carry out the provisions of this subchapter. Such regulations shall take into account the difference in concept and usage between various classes of pesticides, including public health pesticides, and differences in environmental risk and the appropriate data for evaluating such risk between agricultural, nonagricultural, and public health pesticides."],[0,"(2) Procedure"],[0,"(A) Proposed regulations"],[2,"At least 60 days prior to signing any proposed regulation for publication in the Federal Register, the Administrator shall provide the Secretary of Agriculture with a copy of such regulation. If the Secretary comments in writing to the Administrator regarding any such regulation within 30 days after receiving it, the Administrator shall publish in the Federal Register (with the proposed regulation) the comments of the Secretary and the response of the Administrator with regard to the Secretary's comments. If the Secretary does not comment in writing to the Administrator regarding the regulation within 30 days after receiving it, the Administrator may sign such regulation for publication in the Federal Register any time after such 30-day period notwithstanding the foregoing 60-day time requirement."],[0,"(B) Final regulations"],[2,"At least 30 days prior to signing any regulation in final form for publication in the Federal Register, the Administrator shall provide the Secretary of Agriculture with a copy of such regulation. If the Secretary comments in writing to the Administrator regarding any such final regulation within 15 days after receiving it, the Administrator shall publish in the Federal Register (with the final regulation) the comments of the Secretary, if requested by the Secretary, and the response of the Administrator concerning the Secretary's comments. If the Secretary does not comment in writing to the Administrator regarding the regulation within 15 days after receiving it, the Administrator may sign such regulation for publication in the Federal Register at any time after such 15-day period notwithstanding the foregoing 30-day time requirement. In taking any final action under this subsection, the Administrator shall include among those factors to be taken into account the effect of the regulation on production and prices of agricultural commodities, retail food prices, and otherwise on the agricultural economy, and the Administrator shall publish in the Federal Register an analysis of such effect."],[0,"(C) Time requirements"],[2,"The time requirements imposed by subparagraphs (A) and (B) may be waived or modified to the extent agreed upon by the Administrator and the Secretary."],[0,"(D) Publication in the Federal Register"],[2,"The Administrator shall, simultaneously with any notification to the Secretary of Agriculture under this paragraph prior to the issuance of any proposed or final regulation, publish such notification in the Federal Register."],[0,"(3) Congressional committees"],[1,"At such time as the Administrator is required under paragraph (2) of this subsection to provide the Secretary of Agriculture with a copy of proposed regulations and a copy of the final form of regulations, the Administrator shall also furnish a copy of such regulations to the Committee on Agriculture of the House of Representatives and the Committee on Agriculture, Nutrition, and Forestry of the Senate."],[0,"(4) Congressional review of regulations"],[1,"Simultaneously with the promulgation of any rule or regulation under this subchapter, the Administrator shall transmit a copy thereof to the Secretary of the Senate and the Clerk of the House of Representatives. The rule or regulation shall not become effective until the passage of 60 calendar days after the rule or regulation is so transmitted."],[0,"(b) Exemption of pesticides"],[0,"The Administrator may exempt from the requirements of this subchapter by regulation any pesticide which the Administrator determines either (1) to be adequately regulated by another Federal agency, or (2) to be of a character which is unnecessary to be subject to this subchapter in order to carry out the purposes of this subchapter."],[0,"(c) Other authority"],[0,"The Administrator, after notice and opportunity for hearing, is authorized—"],[1,"(1) to declare a pest any form of plant or animal life (other than man and other than bacteria, virus, and other micro-organisms on or in living man or other living animals) which is injurious to health or the environment;"],[1,"(2) to determine any pesticide which contains any substance or substances in quantities highly toxic to man;"],[1,"(3) to establish standards (which shall be consistent with those established under the authority of the Poison Prevention Packaging Act (Public Law 91–601) [15 U.S.C. 1471 et seq.]) with respect to the package, container, or wrapping in which a pesticide or device is enclosed for use or consumption, in order to protect children and adults from serious injury or illness resulting from accidental ingestion or contact with pesticides or devices regulated by this subchapter as well as to accomplish the other purposes of this subchapter;"],[1,"(4) to specify those classes of devices which shall be subject to any provision of section 136(q)(1) or section 136e of this title upon the Administrator's determination that application of such provision is necessary to effectuate the purposes of this subchapter;"],[1,"(5) to prescribe regulations requiring any pesticide to be colored or discolored if the Administrator determines that such requirement is feasible and is necessary for the protection of health and the environment; and"],[1,"(6) to determine and establish suitable names to be used in the ingredient statement."],[0,"(d) Scientific advisory panel"],[0,"(1) In general"],[1,"The Administrator shall submit to an advisory panel for comment as to the impact on health and the environment of the action proposed in notices of intent issued under section 136d(b) of this title and of the proposed and final form of regulations issued under subsection (a) within the same time periods as provided for the comments of the Secretary of Agriculture under such section 136d(b) and subsection (a) of this section. The time requirements for notices of intent and proposed and final forms of regulation may not be modified or waived unless in addition to meeting the requirements of section 136d(b) of this title or subsection (a) of this section, as applicable, the advisory panel has failed to comment on the proposed action within the prescribed time period or has agreed to the modification or waiver. The Administrator shall also solicit from the advisory panel comments, evaluations, and recommendations for operating guidelines to improve the effectiveness and quality of scientific analyses made by personnel of the Environmental Protection Agency that lead to decisions by the Administrator in carrying out the provisions of this subchapter. The comments, evaluations, and recommendations of the advisory panel submitted under this subsection and the response of the Administrator shall be published in the Federal Register in the same manner as provided for publication of the comments of the Secretary of Agriculture under such sections. The chairman of the advisory panel, after consultation with the Administrator, may create temporary subpanels on specific projects to assist the full advisory panel in expediting and preparing its evaluations, comments, and recommendations. The subpanels may be composed of scientists other than members of the advisory panel, as deemed necessary for the purpose of evaluating scientific studies relied upon by the Administrator with respect to proposed action. Such additional scientists shall be selected by the advisory panel. The panel referred to in this subsection shall consist of 7 members appointed by the Administrator from a list of 12 nominees, 6 nominated by the National Institutes of Health and 6 by the National Science Foundation, utilizing a system of staggered terms of appointment. Members of the panel shall be selected on the basis of their professional qualifications to assess the effects of the impact of pesticides on health and the environment. To the extent feasible to insure multidisciplinary representation, the panel membership shall include representation from the disciplines of toxicology, pathology, environmental biology, and related sciences. If a vacancy occurs on the panel due to expiration of a term, resignation, or any other reason, each replacement shall be selected by the Administrator from a group of 4 nominees, 2 submitted by each of the nominating entities named in this subsection. The Administrator may extend the term of a panel member until the new member is appointed to fill the vacancy. If a vacancy occurs due to resignation, or reason other than expiration of a term, the Administrator shall appoint a member to serve during the unexpired term utilizing the nomination process set forth in this subsection. Should the list of nominees provided under this subsection be unsatisfactory, the Administrator may request an additional set of nominees from the nominating entities. The Administrator may require such information from the nominees to the advisory panel as the Administrator deems necessary, and the Administrator shall publish in the Federal Register the name, address, and professional affiliations of each nominee. Each member of the panel shall receive per diem compensation at a rate not in excess of that fixed for GS–18 of the General Schedule as may be determined by the Administrator, except that any such member who holds another office or position under the Federal Government the compensation for which exceeds such rate may elect to receive compensation at the rate provided for such other office or position in lieu of the compensation provided by this subsection. In order to assure the objectivity of the advisory panel, the Administrator shall promulgate regulations regarding conflicts of interest with respect to the members of the panel. The advisory panel established under this section shall be permanent. In performing the functions assigned by this subchapter, the panel shall consult and coordinate its activities with the Science Advisory Board established under the Environmental Research, Development, and Demonstration Authorization Act of 1978 [42 U.S.C. 4365]. Whenever the Administrator exercises authority under section 136d(c) of this title to immediately suspend the registration of any pesticide to prevent an imminent hazard, the Administrator shall promptly submit to the advisory panel for comment, as to the impact on health and the environment, the action taken to suspend the registration of such pesticide."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136w?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§136w. Authority of Administrator","tname":"Agriculture","by":{"0":"24","1":"1"}},{"t":"usc","label":"21 U.S.C. § 360k","url":"https://www.law.cornell.edu/uscode/text/21/360k","subs":["(a)","(a)(1)"],"stext":{"head":"§360k. State and local requirements respecting devices","paras":[[0,"(a) General rule"],[0,"Except as provided in subsection (b), no State or political subdivision of a State may establish or continue in effect with respect to a device intended for human use any requirement—"],[1,"(1) which is different from, or in addition to, any requirement applicable under this chapter to the device, and"],[1,"(2) which relates to the safety or effectiveness of the device or to any other matter included in a requirement applicable to the device under this chapter."],[0,"(b) Exempt requirements"],[0,"Upon application of a State or a political subdivision thereof, the Secretary may, by regulation promulgated after notice and opportunity for an oral hearing, exempt from subsection (a), under such conditions as may be prescribed in such regulation, a requirement of such State or political subdivision applicable to a device intended for human use if—"],[1,"(1) the requirement is more stringent than a requirement under this chapter which would be applicable to the device if an exemption were not in effect under this subsection; or"],[1,"(2) the requirement—"],[2,"(A) is required by compelling local conditions, and"],[2,"(B) compliance with the requirement would not cause the device to be in violation of any applicable requirement under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360k?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§360k. State and local requirements respecting devices","tname":"Food and Drugs","by":{"0":"29","1":"12, 21","2":"50"}},{"t":"law","label":"Pub. L. No. 80-104","by":{"0":"4, 5"}},{"t":"law","label":"Pub. L. No. 88-305","url":"https://www.govinfo.gov/link/statute/78/190","by":{"0":"5","1":"26"}},{"t":"law","label":"Pub. L. No. 92-516","url":"https://www.govinfo.gov/link/statute/86/973","by":{"0":"4, 5, 6","1":"27","3":"11"}},{"t":"reg","label":"40 C.F.R. § 152.40","url":"https://www.ecfr.gov/current/title-40/section-152.40","by":{"0":"8, 30"}},{"t":"reg","label":"40 C.F.R. § 152.44","url":"https://www.ecfr.gov/current/title-40/section-152.44","subs":["(a)"],"by":{"0":"9, 30, 45, 25, 45","2":"39","4":"18"}},{"t":"reg","label":"40 C.F.R. § 152.46","url":"https://www.ecfr.gov/current/title-40/section-152.46","subs":["(a)(1)","(a)"],"by":{"0":"9, 30, 45","2":"39, 40","3":"18","4":"18"}},{"t":"reg","label":"40 C.F.R. § 152.50","url":"https://www.ecfr.gov/current/title-40/section-152.50","subs":["(e)","(f)(3)"],"by":{"0":"45","3":"18, 18"}},{"t":"reg","label":"40 C.F.R. § 152.80","url":"https://www.ecfr.gov/current/title-40/section-152.80","by":{"0":"24"}},{"t":"reg","label":"40 C.F.R. § 152.85","url":"https://www.ecfr.gov/current/title-40/section-152.85","subs":["(e)"],"by":{"0":"8, 42"}},{"t":"reg","label":"40 C.F.R. § 152.105","url":"https://www.ecfr.gov/current/title-40/section-152.105","by":{"0":"24"}},{"t":"reg","label":"40 C.F.R. § 152.112","url":"https://www.ecfr.gov/current/title-40/section-152.112","subs":["(e)","(f)"],"by":{"0":"7, 30, 23, 7, 30, 8, 23"}},{"t":"reg","label":"40 C.F.R. § 152.170","url":"https://www.ecfr.gov/current/title-40/section-152.170","subs":["(a)(4)","(a)","(a)(2)","(e)(2)"],"by":{"0":"42","4":"13, 13, 13"}},{"t":"reg","label":"40 C.F.R. § 152.171","url":"https://www.ecfr.gov/current/title-40/section-152.171","subs":["(b)"],"by":{"0":"42"}},{"t":"reg","label":"40 C.F.R. § 154.1","url":"https://www.ecfr.gov/current/title-40/section-154.1","subs":["(a)"],"by":{"0":"43"}},{"t":"reg","label":"40 C.F.R. § 154.25","url":"https://www.ecfr.gov/current/title-40/section-154.25","subs":["(d)"],"by":{"0":"24"}},{"t":"reg","label":"40 C.F.R. § 154.7","url":"https://www.ecfr.gov/current/title-40/section-154.7","subs":["(a)(5)"],"by":{"0":"43"}},{"t":"reg","label":"40 C.F.R. § 155.40","url":"https://www.ecfr.gov/current/title-40/section-155.40","subs":["(a)(2)"],"by":{"0":"9"}},{"t":"reg","label":"40 C.F.R. § 155.53","url":"https://www.ecfr.gov/current/title-40/section-155.53","subs":["(a)"],"by":{"0":"42"}},{"t":"reg","label":"40 C.F.R. § 155.58","url":"https://www.ecfr.gov/current/title-40/section-155.58","subs":["(b)(4)"],"by":{"0":"9, 8, 38, 50"}},{"t":"reg","label":"40 C.F.R. § 156.10","url":"https://www.ecfr.gov/current/title-40/section-156.10","subs":["(a)(1)","(a)(5)(vii)","(h)(2)"],"by":{"0":"8, 24","2":"10","4":"19"}},{"t":"reg","label":"40 C.F.R. § 156.60","url":"https://www.ecfr.gov/current/title-40/section-156.60","by":{"0":"8, 24"}},{"t":"reg","label":"40 C.F.R. § 156.70","url":"https://www.ecfr.gov/current/title-40/section-156.70","subs":["(c)","(a)"],"by":{"0":"9, 25, 45","4":"19, 18"}},{"t":"reg","label":"40 C.F.R. § 158.1","url":"https://www.ecfr.gov/current/title-40/section-158.1","subs":["(a)"],"by":{"0":"43"}},{"t":"reg","label":"40 C.F.R. § 158.45","url":"https://www.ecfr.gov/current/title-40/section-158.45","subs":["(a)"],"by":{"0":"43"}},{"t":"reg","label":"40 C.F.R. § 158.500","url":"https://www.ecfr.gov/current/title-40/section-158.500","by":{"0":"8, 24"}},{"t":"reg","label":"40 C.F.R. § 159.152","url":"https://www.ecfr.gov/current/title-40/section-159.152","by":{"0":"9","3":"19"}},{"t":"reg","label":"40 C.F.R. § 159.158","url":"https://www.ecfr.gov/current/title-40/section-159.158","subs":["(a)"],"by":{"0":"38"}},{"t":"reg","label":"40 C.F.R. § 166.3","url":"https://www.ecfr.gov/current/title-40/section-166.3","by":{"0":"23, 30"}},{"t":"reg","label":"49 Fed. Reg. 37,960","url":"https://www.govinfo.gov/link/fr/49/37960","by":{"0":"40"}},{"t":"reg","label":"73 Fed. Reg. 73,586","url":"https://www.govinfo.gov/link/fr/73/73586","by":{"0":"12"}},{"t":"case","label":"Buckman Co. v. Plaintiffs’ Legal Comm.","cite":"531 U.S. 341","y":2001,"id":"2000/98-1768","sc":1,"ar":1,"sum":"The Court held that the plaintiffs' state-law fraud-on-the-FDA claims conflicted with, and were therefore pre-empted by, the FDCA, as amended by the MDA. \"The conflict,\" wrote Chief Justice Rehnquist for the Court, \"stems from the fact that the federal statutory scheme amply empowers the FDA to punish and deter fraud against the Agency, and that this authority is used by the Agency to achieve a somewhat delicate balance of statutory objectives.","sumSrc":"Oyez","by":{"1":"17","4":"12"}},{"t":"case","label":"Chrysler Corp. v. Brown","cite":"441 U.S. 281","y":1979,"id":"1978/77-922","sc":1,"sum":"Petitioner, as a party to numerous Government contracts, was required to comply with Executive Orders 11246 and 11375, which charge the Secretary of Labor with ensuring that corporations that benefit from Government contracts provide equal employment opportunity regardless of race or sex. Regulations promulgated by the Department of Labor's Office of Federal Contract Compliance Programs (OFCCP) require Government …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Hardeman v. Monsanto Co.","cite":"997 F.3d 941","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/997/941/","op":2,"by":{"1":"14"}},{"t":"case","label":"Jones v. Rath Packing Co.","cite":"430 U.S. 519","y":1977,"id":"1976/75-1053","sc":1,"sum":"Section 12211 of the California Business and Professions Code provides that \"the average weight or measure of the packages or containers in a lot of any... commodity sampled shall not be less, at the time of sale or offer for sale, than the net weight or measure stated upon the package.\" Article 5, § 2930 et seq., of Title 4 of the California Administrative Code in implementing § 12211 requires a statistical …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Lipschultz v. Charter Adv. Servs. (MN), LLC","cite":"589 U.S. 1038","y":2019,"url":"https://supreme.justia.com/cases/federal/us/589/1038/","sc":1,"by":{"1":"20"}},{"t":"case","label":"National Meat Ass’n v. Harris","cite":"565 U.S. 452","y":2012,"id":"2011/10-224","sc":1,"sum":"The Court held that a California law requiring slaughterhouses to \"immediately euthanize\" any nonambulatory animal on its premises is preempted by the Federal Meat Inspection Act.","sumSrc":"Oyez","by":{"1":"15","4":"9"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Defense","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Natural Res. Def. Council v. EPA","cite":"31 F.4th 1203","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/31/1203/","op":1,"by":{"1":"7"}},{"t":"case","label":"Newman v. Ford Motor Co.","cite":"975 S.W.2d 147","y":1998,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/975/147/","by":{"1":"24, 25"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Trust","cite":"579 U.S. 115","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"United States Army Corps of Eng’rs v. Hawkes","cite":"578 U.S. 590","y":2016,"id":"2015/15-290","sc":1,"sum":"The Court determined that the Army Corps of Engineers’ jurisdictional determination that a property constituted “water of the United States” was a final agency action subject to judicial review under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Van Buren v. United States","cite":"593 U.S. 374","y":2021,"id":"2020/19-783","sc":1,"sum":"An individual “exceeds authorized access” under the Computer Fraud and Abuse Act of 1986, 18 U. S. C. §1030(a)(2), when he accesses a computer with authorization but then obtains information located in particular areas of the computer—such as files, folders, or databases—that are off-limits to him.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"Wisconsin Public Intervenor v. Mortier","cite":"501 U.S. 597","y":1991,"id":"1990/89-1905","sc":1,"op":2,"sum":"FIFRA does not pre-empt local governmental regulation of pesticide use.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"5","2":"7","3":"2, 9, 10"}},{"t":"usc","label":"21 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/21/301","by":{"1":"21"}},{"t":"usc","label":"7 U.S.C. § 136l","url":"https://www.law.cornell.edu/uscode/text/7/136l","subs":["(b)","(a)(1)"],"stext":{"head":"§136l. Penalties","paras":[[0,"(a) Civil penalties"],[0,"(1) In general"],[1,"Any registrant, commercial applicator, wholesaler, dealer, retailer, or other distributor who violates any provision of this subchapter may be assessed a civil penalty by the Administrator of not more than $5,000 for each offense."],[0,"(2) Private applicator"],[1,"Any private applicator or other person not included in paragraph (1) who violates any provision of this subchapter subsequent to receiving a written warning from the Administrator or following a citation for a prior violation, may be assessed a civil penalty by the Administrator of not more than $1,000 for each offense, except that any applicator not included under paragraph (1) of this subsection who holds or applies registered pesticides, or uses dilutions of registered pesticides, only to provide a service of controlling pests without delivering any unapplied pesticide to any person so served, and who violates any provision of this subchapter may be assessed a civil penalty by the Administrator of not more than $500 for the first offense nor more than $1,000 for each subsequent offense."],[0,"(3) Hearing"],[1,"No civil penalty shall be assessed unless the person charged shall have been given notice and opportunity for a hearing on such charge in the county, parish, or incorporated city of the residence of the person charged."],[0,"(4) Determination of penalty"],[1,"In determining the amount of the penalty, the Administrator shall consider the appropriateness of such penalty to the size of the business of the person charged, the effect on the person's ability to continue in business, and the gravity of the violation. Whenever the Administrator finds that the violation occurred despite the exercise of due care or did not cause significant harm to health or the environment, the Administrator may issue a warning in lieu of assessing a penalty."],[0,"(5) References to Attorney General"],[1,"In case of inability to collect such civil penalty or failure of any person to pay all, or such portion of such civil penalty as the Administrator may determine, the Administrator shall refer the matter to the Attorney General, who shall recover such amount by action in the appropriate United States district court."],[0,"(b) Criminal penalties"],[0,"(1) In general"],[1,"(A) Any registrant, applicant for a registration, or producer who knowingly violates any provision of this subchapter shall be fined not more than $50,000 or imprisoned for not more than 1 year, or both."],[1,"(B) Any commercial applicator of a restricted use pesticide, or any other person not described in subparagraph (A) who distributes or sells pesticides or devices, who knowingly violates any provision of this subchapter shall be fined not more than $25,000 or imprisoned for not more than 1 year, or both."],[0,"(2) Private applicator"],[1,"Any private applicator or other person not included in paragraph (1) who knowingly violates any provision of this subchapter shall be guilty of a misdemeanor and shall on conviction be fined not more than $1,000, or imprisoned for not more than 30 days, or both."],[0,"(3) Disclosure of information"],[1,"Any person, who, with intent to defraud, uses or reveals information relative to formulas of products acquired under the authority of section 136a of this title, shall be fined not more than $10,000, or imprisoned for not more than three years, or both."],[0,"(4) Acts of officers, agents, etc."],[1,"When construing and enforcing the provisions of this subchapter, the act, omission, or failure of any officer, agent, or other person acting for or employed by any person shall in every case be also deemed to be the act, omission, or failure of such person as well as that of the person employed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136l?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§136l. Penalties","tname":"Agriculture","by":{"1":"5, 21, 20","2":"31, 31"}},{"t":"usc","label":"7 U.S.C. § 136n","url":"https://www.law.cornell.edu/uscode/text/7/136n","subs":["(b)"],"stext":{"head":"§136n. Administrative procedure; judicial review","paras":[[0,"(a) District court review"],[0,"Except as otherwise provided in this subchapter, the refusal of the Administrator to cancel or suspend a registration or to change a classification not following a hearing and other final actions of the Administrator not committed to the discretion of the Administrator by law are judicially reviewable by the district courts of the United States."],[0,"(b) Review by court of appeals"],[0,"In the case of actual controversy as to the validity of any order issued by the Administrator following a public hearing, any person who will be adversely affected by such order and who had been a party to the proceedings may obtain judicial review by filing in the United States court of appeals for the circuit wherein such person resides or has a place of business, within 60 days after the entry of such order, a petition praying that the order be set aside in whole or in part. A copy of the petition shall be forthwith transmitted by the clerk of the court to the Administrator or any officer designated by the Administrator for that purpose, and thereupon the Administrator shall file in the court the record of the proceedings on which the Administrator based the Administrator's order, as provided in section 2112 of title 28. Upon the filing of such petition the court shall have exclusive jurisdiction to affirm or set aside the order complained of in whole or in part. The court shall consider all evidence of record. The order of the Administrator shall be sustained if it is supported by substantial evidence when considered on the record as a whole. The judgment of the court affirming or setting aside, in whole or in part, any order under this section shall be final, subject to review by the Supreme Court of the United States upon certiorari or certification as provided in section 1254 of title 28. The commencement of proceedings under this section shall not, unless specifically ordered by the court to the contrary, operate as a stay of an order."],[0,"(c) Jurisdiction of district courts"],[0,"The district courts of the United States are vested with jurisdiction specifically to enforce, and to prevent and restrain violations of, this subchapter."],[0,"(d) Notice of judgments"],[0,"The Administrator shall, by publication in such manner as the Administrator may prescribe, give notice of all judgments entered in actions instituted under the authority of this subchapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/136n?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§136n. Administrative procedure; judicial review","tname":"Agriculture","by":{"1":"7","2":"2"}},{"t":"usc","label":"21 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/21/601","by":{"1":"15"}},{"t":"usc","label":"21 U.S.C. § 678","url":"https://www.law.cornell.edu/uscode/text/21/678","stext":{"head":"§678. Non-Federal jurisdiction of federally regulated matters; prohibition of additional or different requirements for establishments with inspection services and as to marking, labeling, packaging, and ingredients; recordkeeping and related requirements; concurrent jurisdiction over distribution for human food purposes of adulterated or misbranded and imported articles; other matters","paras":[[0,"Requirements within the scope of this chapter with respect to premises, facilities and operations of any establishment at which inspection is provided under subchapter I of this chapter, which are in addition to, or different than those made under this chapter may not be imposed by any State or Territory or the District of Columbia, except that any such jurisdiction may impose recordkeeping and other requirements within the scope of section 642 of this title, if consistent therewith, with respect to any such establishment. Marking, labeling, packaging, or ingredient requirements in addition to, or different than, those made under this chapter may not be imposed by any State or Territory or the District of Columbia with respect to articles prepared at any establishment under inspection in accordance with the requirements under subchapter I of this chapter, but any State or Territory or the District of Columbia may, consistent with the requirements under this chapter, exercise concurrent jurisdiction with the Secretary over articles required to be inspected under said subchapter I, for the purpose of preventing the distribution for human food purposes of any such articles which are adulterated or misbranded and are outside of such an establishment, or, in the case of imported articles which are not at such an establishment, after their entry into the United States. This chapter shall not preclude any State or Territory or the District of Columbia from making requirement 1 or taking other action, consistent with this chapter, with respect to any other matters regulated under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/678?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§678. Non-Federal jurisdiction of federally regulated matters; prohibition of additional or different requirements for establishments with inspection services and as to marking, labeling, packaging, and ingredients; recordkeeping and related requirements; concurrent jurisdiction over distribution for human food purposes of adulterated or misbranded and imported articles; other matters","tname":"Food and Drugs","by":{"1":"15, 18"}},{"t":"law","label":"Pub. L. No. 94-295","url":"https://www.govinfo.gov/link/statute/90/539","by":{"1":"12, 21"}},{"t":"usc","label":"21 U.S.C. § 360e","url":"https://www.law.cornell.edu/uscode/text/21/360e","subs":["(d)(5)(A)(i)"],"stext":{"head":"§360e. Premarket approval","paras":[[0,"(a) General requirement"],[0,"A class III device—"],[1,"(1) which is subject to an order issued under subsection (b) (or a regulation promulgated under such subsection prior to July 9, 2012); or"],[1,"(2) which is a class III device because of section 360c(f) of this title,"],[0,"is required to have, unless exempt under section 360j(g) of this title, an approval under this section of an application for premarket approval or, as applicable, an approval under subsection (c)(2) of a report seeking premarket approval."],[0,"(b) Order to require premarket approval"],[0,"(1) In the case of a class III device which—"],[1,"(A) was introduced or delivered for introduction into interstate commerce for commercial distribution before May 28, 1976; or"],[1,"(B) is (i) of a type so introduced or delivered, and (ii) is substantially equivalent to another device within that type,"],[0,"the Secretary shall by administrative order following publication of a proposed order in the Federal Register, a meeting of a device classification panel described in section 360c(b) of this title, and consideration of comments from all affected stakeholders, including patients, payors, and providers, notwithstanding subchapter II of chapter 5 of title 5, require that such device have an approval under this section of an application for premarket approval. Authority to issue such administrative order shall not be delegated below the Director of the Center for Devices and Radiological Health, acting in consultation with the Commissioner."],[0,"(2) A proposed order required under paragraph (1) shall contain—"],[1,"(A) the proposed order;"],[1,"(B) proposed findings with respect to the degree of risk of illness or injury designed to be eliminated or reduced by requiring the device to have an approved application for premarket approval and the benefit to the public from use of the device;"],[1,"(C) opportunity for the submission of comments on the proposed order and the proposed findings; and"],[1,"(D) opportunity to request a change in the classification of the device based on new information relevant to the classification of the device."],[0,"(3) After the expiration of the period for comment on a proposed order and proposed findings published under paragraph (2), consideration of comments submitted on such proposed order and findings, and a meeting of a device classification panel described in section 360c(b) of this title, the Secretary shall (A) issue an administrative order under paragraph (1) and publish in the Federal Register findings on the matters referred to in paragraph (2)(B), or (B) publish a notice terminating the proceeding for the issuance of the administrative order together with the reasons for such termination. If a notice of termination is published, the Secretary shall (unless such notice is issued because the device is a banned device under section 360f of this title) initiate a proceeding under section 360c(e) of this title to reclassify the device subject to the proceeding terminated by such notice."],[0,"(c) Application for premarket approval"],[0,"(1) Any person may file with the Secretary an application for premarket approval for a class III device. Such an application for a device shall contain—"],[1,"(A) full reports of all information, published or known to or which should reasonably be known to the applicant, concerning investigations which have been made to show whether or not such device is safe and effective;"],[1,"(B) a full statement of the components, ingredients, and properties and of the principle or principles of operation, of such device;"],[1,"(C) a full description of the methods used in, and the facilities and controls used for, the manufacture, processing, and, when relevant, packing and installation of, such device;"],[1,"(D) an identifying reference to any performance standard under section 360d of this title which would be applicable to any aspect of such device if it were a class II device, and either adequate information to show that such aspect of such device fully meets such performance standard or adequate information to justify any deviation from such standard;"],[1,"(E) such samples of such device and of components thereof as the Secretary may reasonably require, except that where the submission of such samples is impracticable or unduly burdensome, the requirement of this subparagraph may be met by the submission of complete information concerning the location of one or more such devices readily available for examination and testing;"],[1,"(F) specimens of the labeling proposed to be used for such device;"],[1,"(G) the certification required under section 282(j)(5)(B) of title 42 (which shall not be considered an element of such application); and"],[1,"(H) such other information relevant to the subject matter of the application as the Secretary, with the concurrence of the appropriate panel under section 360c of this title, may require."],[0,"(2)(A) Any person may file with the Secretary a report seeking premarket approval for a class III device referred to in subsection (a) that is a reprocessed single-use device. Such a report shall contain the following:"],[1,"(i) The device name, including both the trade or proprietary name and the common or usual name."],[1,"(ii) The establishment registration number of the owner or operator submitting the report."],[1,"(iii) Actions taken to comply with performance standards under section 360d of this title."],[1,"(iv) Proposed labels, labeling, and advertising sufficient to describe the device, its intended use, and directions for use."],[1,"(v) Full reports of all information, published or known to or which should be reasonably known to the applicant, concerning investigations which have been made to show whether or not the device is safe or effective."],[1,"(vi) A description of the device's components, ingredients, and properties."],[1,"(vii) A full description of the methods used in, and the facilities and controls used for, the reprocessing and packing of the device."],[1,"(viii) Such samples of the device that the Secretary may reasonably require."],[1,"(ix) A financial certification or disclosure statement or both, as required by part 54 of title 21, Code of Federal Regulations."],[1,"(x) A statement that the applicant believes to the best of the applicant's knowledge that all data and information submitted to the Secretary are truthful and accurate and that no material fact has been omitted in the report."],[1,"(xi) Any additional data and information, including information of the type required in paragraph (1) for an application under such paragraph, that the Secretary determines is necessary to determine whether there is reasonable assurance of safety and effectiveness for the reprocessed device."],[1,"(xii) Validation data described in section 360(o)(1)(A) of this title that demonstrates that the reasonable assurance of the safety or effectiveness of the device will remain after the maximum number of times the device is reprocessed as intended by the person submitting such report."],[0,"(B) In the case of a class III device referred to in subsection (a) that is a reprocessed single-use device:"],[1,"(i) Subparagraph (A) of this paragraph applies in lieu of paragraph (1)."],[1,"(ii) Subject to clause (i), the provisions of this section apply to a report under subparagraph (A) to the same extent and in the same manner as such provisions apply to an application under paragraph (1)."],[1,"(iii) Each reference in other sections of this chapter to an application under this section, other than such a reference in section 379i or 379j of this title, shall be considered to be a reference to a report under subparagraph (A)."],[1,"(iv) Each reference in other sections of this chapter to a device for which an application under this section has been approved, or has been denied, suspended, or withdrawn, other than such a reference in section 379i or 379j of this title, shall be considered to be a reference to a device for which a report under subparagraph (A) has been approved, or has been denied, suspended, or withdrawn, respectively."],[0,"(3) Upon receipt of an application meeting the requirements set forth in paragraph (1), the Secretary—"],[1,"(A) may on the Secretary's own initiative, or"],[1,"(B) shall, upon the request of an applicant unless the Secretary finds that the information in the application which would be reviewed by a panel substantially duplicates information which has previously been reviewed by a panel appointed under section 360c of this title,"],[0,"refer such application to the appropriate panel under section 360c of this title for study and for submission (within such period as he may establish) of a report and recommendation respecting approval of the application, together with all underlying data and the reasons or basis for the recommendation. Where appropriate, the Secretary shall ensure that such panel includes, or consults with, one or more pediatric experts."],[0,"(4)(A) Prior to the submission of an application under this subsection, the Secretary shall accept and review any portion of the application that the applicant and the Secretary agree is complete, ready, and appropriate for review, except that such requirement does not apply, and the Secretary has discretion whether to accept and review such portion, during any period in which, under section 379j(g) of this title, the Secretary does not have the authority to collect fees under section 379j(a) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/360e?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§360e. Premarket approval","tname":"Food and Drugs","by":{"1":"22"}},{"t":"case","label":"B&B Hardware, Inc. v. Hargis Industries, Inc.","cite":"575 U.S. 138","y":2015,"id":"2014/13-352","sc":1,"sum":"The Court held that a decision on an issue by an administrative agency can preclude re-litigation of that issue in federal court.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"English v. General Electric Co.","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"sum":"English's state-law claim for intentional infliction of emotional distress is not pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"op":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Haberly v. Reardon Co.","cite":"319 S.W.2d 859","y":1958,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/319/859/","by":{"2":"12, 33"}},{"t":"case","label":"La Plant v. E.I. DuPont De Nemours & Co.","cite":"346 S.W.2d 231","y":1961,"court":"Mo. Ct. App.","url":"https://www.courtlistener.com/c/S.W.2d/346/231/","by":{"2":"12, 33"}},{"t":"case","label":"Loper Bright Enterprises v. Raimondo","cite":"603 U.S. 369","y":2024,"id":"2023/22-451","sc":1,"op":1,"ar":9,"sum":"The Administrative Procedure Act requires courts to exercise their independent judgment in deciding whether an agency has acted within its statutory authority, and courts may not defer to an agency interpretation of the law simply because a statute is ambiguous; Chevron U. S. A. Inc. v. Natural Resources Defense Council, Inc., 467 U. S. 837, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5, 10, 11, 21, 22, 24, 25, 26","4":"1"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","by":{"2":"24"}},{"t":"case","label":"Meeker v. Lehigh Valley R. Co.","cite":"236 U.S. 412","y":1915,"id":"scdb/1914-227","sc":1,"sum":"The limitations in Rev. Stat., § 1047, on suits for penalties accruing under the laws of the United States, relate to punitive penalties for infractions of public law. and not to liabilities imposed for redressing a private injury even though the wrongful act be a public oifense and punishable as such. It does not relate to a liability accruing under §§ 8, 9, 14 and 16 of the Act to Regulate Commerce which is not …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"National Cable & Telecommunications Association v. Brand X Internet Services","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"2":"47"}},{"t":"case","label":"Nesselrode v. Executive Beechcraft, Inc.","cite":"707 S.W.2d 371","y":1986,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/707/371/","by":{"2":"12, 13, 33"}},{"t":"case","label":"(vii) Racer v. Utterman","cite":"629 S.W.2d 387","y":1981,"court":"Mo. Ct. App.","url":"https://www.courtlistener.com/c/S.W.2d/629/387/","op":1,"by":{"2":"3, 12, 13, 44"}},{"t":"case","label":"SEC v. Jarkesy","cite":"603 U.S. 109","y":2024,"url":"https://supreme.justia.com/cases/federal/us/603/109/","sc":1,"by":{"2":"31"}},{"t":"case","label":"Theatre Enterprises, Inc. v. Paramount Film Distributing Corp.","cite":"346 U.S. 537","y":1954,"id":"1940-1955/346us537","sc":1,"sum":"Petitioner brought suit in a Federal District Court under the Clayton Act for treble damages and an injunction, alleging that respondent motion picture producers and distributors had violated the antitrust laws by conspiring to restrict \"first-run\" pictures to downtown Baltimore theatres, thus confining petitioner's suburban theatre to subsequent runs and unreasonable \"clearances.\" There was no direct evidence of …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"Trump v. CASA, Inc.","cite":"606 U.S. 831","y":2025,"id":"2024/24a884","sc":1,"sum":"Because universal injunctions likely exceed the equitable authority that Congress has granted to federal courts, the Court grants the Government’s applications for a partial stay of the injunctions entered below regarding the implementation and enforcement of President Trump’s Executive Order No. 14160, but only to the extent that the injunctions are broader than necessary to provide complete relief to each plaintiff with standing to sue.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"45"}},{"t":"case","label":"United States v. Carolene Products Co.","cite":"304 U.S. 144","y":1938,"id":"1900-1940/304us144","sc":1,"sum":"A case in which the Court upheld a federal law banning the interstate shipment of \"filled milk\" because Congress had a rational basis for enacting it.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"ar":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"2":"10, 26"}},{"t":"usc","label":"21 U.S.C. § 331","url":"https://www.law.cornell.edu/uscode/text/21/331","by":{"2":"49"}},{"t":"usc","label":"28 U.S.C. § 453","url":"https://www.law.cornell.edu/uscode/text/28/453","by":{"2":"27"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"2":"31"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"2":"4"}},{"t":"reg","label":"21 C.F.R. § 314.70","url":"https://www.ecfr.gov/current/title-21/section-314.70","subs":["(c)(1)","(c)(6)","(c)(7)"],"by":{"2":"42, 36, 42"}},{"t":"reg","label":"EPA, Pesticides; Guidance for Pesticide Registrants on Mandatory and Advisory Labeling Statements, 65 Fed. Reg. 31,313","url":"https://www.govinfo.gov/link/fr/65/31313","by":{"2":"41"}},{"t":"reg","label":"Executive Order No. 14387, Promoting the National Defense by Ensuring an Adequate Supply of Elemental Phosphorus and Glyphosate-Based Herbic, 91 Fed. Reg. 8703","url":"https://www.govinfo.gov/link/fr/91/8703","by":{"2":"28"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"3":"2, 11"}},{"t":"case","label":"Learning Resources, Inc. v. Trump, 607 U.S. ---","cite":"146 S. Ct. 628","y":2026,"id":"2025/24-1287","sc":1,"op":1,"sum":"The International Emergency Economic Powers Act, 91 Stat. 1626, does not authorize the President to impose tariffs.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"2"}},{"t":"reg","label":"40 C.F.R. § 152.42","url":"https://www.ecfr.gov/current/title-40/section-152.42","by":{"3":"18"}},{"t":"reg","label":"40 C.F.R. § 159.155","url":"https://www.ecfr.gov/current/title-40/section-159.155","subs":["(b)"],"by":{"3":"19"}},{"t":"reg","label":"40 C.F.R. § 159.184","url":"https://www.ecfr.gov/current/title-40/section-159.184","subs":["(a)"],"by":{"3":"19"}},{"t":"case","label":"Geier v. Am. Honda Motor","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"ar":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"4":"9"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"4":"4"}},{"t":"case","label":"New York v. FERC","cite":"535 U.S. 1","y":2002,"id":"2001/00-568","sc":1,"op":1,"sum":"The Court held that FERC properly construed its statutory authority.","sumSrc":"Oyez","by":{"4":"10"}},{"t":"case","label":"Pereira v. Sessions","cite":"585 U.S. 198","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"4":"4"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(a)","(j)(2)"],"by":{"4":"22, 22"}}]};